css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .72); position: relative; overflow: hidden; }
.loader::after { content: ''; position: absolute; left: -4%; bottom: 24%; width: 112%; height: 2.5%; border-radius: 999px; transform-origin: left center; transform: rotate(-20deg); background: #94a3b8; }
.loader::before { content: ''; position: absolute; bottom: 0; left: 46%; width: 5%; height: 52%; background: color-mix(in srgb, #000 22%, var(--accent-2)); clip-path: polygon(28% 0, 72% 0, 100% 100%, 0 100%); }
.loader span { position: absolute; left: 0; bottom: 24%; width: 17%; height: 21%; border-radius: 4px 4px 7px 7px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 24%, var(--accent))); animation: ascend calc(var(--loader-speed) * 3.2) linear infinite; }
.loader span::after { content: ''; position: absolute; bottom: 100%; left: 44%; width: 12%; height: 42%; background: var(--accent-2); }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * -.8); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * -1.6); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * -2.4); }
@keyframes ascend { 0% { opacity: 0; transform: translate(-24%, 8%); } 10% { opacity: 1; } 88% { opacity: 1; } 100% { opacity: 0; transform: translate(calc(var(--loader-size) * .92), calc(var(--loader-size) * -.335)); } }
